export type SearchDocument = { id: string; title: string; body: string };
export function tokens(value: string): Set<string> {
  return new Set(value.toLowerCase().match(/[a-z0-9]+/g) ?? []);
}
export function search(records: SearchDocument[], query: string): SearchDocument[] {
  const wanted = tokens(query);
  if (!wanted.size) return [];
  return records.map(record => {
    const found = tokens(record.title + " " + record.body);
    const score = [...wanted].filter(word => found.has(word)).length;
    return { record, score };
  }).filter(item => item.score === wanted.size)
    .sort((a, b) => b.score - a.score || a.record.id.localeCompare(b.record.id))
    .map(item => item.record);
}

import test from "node:test";
import assert from "node:assert/strict";
import { search } from "../src/search.ts";
import { DocumentService } from "../src/service.ts";

for (const [name, runSearch] of [
  ["search", search],
  ["DocumentService.searchDocuments", (records, query) =>
    new DocumentService().searchDocuments(records, query)],
]) {
  test(`${name} requires every whole query token and preserves inputs`, () => {
    const records = Object.freeze([
      Object.freeze({ id: "z", title: "ATLAS", body: "Guide 42" }),
      Object.freeze({ id: "partial", title: "Atlas", body: "unrelated" }),
      Object.freeze({ id: "substring", title: "Atlases", body: "Guide 420" }),
      Object.freeze({ id: "a", title: "Guide: atlas 42", body: "" }),
      Object.freeze({ id: "body", title: "", body: "atlas GUIDE 42" }),
      Object.freeze({ id: "other", title: "Guide 42", body: "" }),
    ]);
    const before = structuredClone(records);
    const result = runSearch(records, "ATLAS, guide-42 atlas");
    assert.deepEqual(result.map(record => record.id), ["a", "body", "z"]);
    assert.equal(result[0], records[3]);
    assert.deepEqual(runSearch(records, "atlas missing"), []);
    assert.deepEqual(runSearch(records, "atl"), []);
    assert.deepEqual(runSearch(records, "42").map(record => record.id),
      ["a", "body", "other", "z"]);
    assert.deepEqual(records, before);
  });

  test(`${name} returns no records for empty normalized queries`, () => {
    const records = [{ id: "a", title: "Atlas", body: "Guide" }];
    for (const query of ["", "   ", "!?---"]) {
      assert.deepEqual(runSearch(records, query), []);
    }
    assert.deepEqual(runSearch([], "atlas"), []);
  });
}

